    const exitMultiplier = exitIntentTriggered ? 1.8 : 1.0;
    const riskScore = (timePenalty + exitMultiplier * 40.0 - valueIncentive) * this.multiplier;
    return Math.max(0.0, Math.min(100.0, riskScore));
